UPDATE campus_monitor_task
task_name = #{taskName}, monitor_subject = #{monitorSubject}, subject_aliases = #{subjectAliases}, keywords = #{keywords}, keywords_i18n = #{keywordsI18n}, negative_words = #{negativeWords}, negative_words_i18n = #{negativeWordsI18n}, exclude_words = #{excludeWords}, exclude_words_i18n = #{excludeWordsI18n}, platform_scope = #{platformScope}, scan_frequency_minutes = #{scanFrequencyMinutes}, schedule_enabled = #{scheduleEnabled}, display_enabled = #{displayEnabled}, auto_ingest_enabled = #{autoIngestEnabled}, alert_mode = #{alertMode}, task_status = #{taskStatus}, next_run_time = #{nextRunTime}, remark = #{remark}, ingest_capability_status = #{ingestCapabilityStatus}, update_user_id = #{updateUserId}
WHERE monitor_task_id = #{monitorTaskId} AND deleted = 0

UPDATE campus_monitor_task
SET task_status = #{taskStatus},
    update_user_id = #{updateUserId}
WHERE monitor_task_id = #{monitorTaskId}
  AND deleted = 0

UPDATE campus_monitor_task
SET display_enabled = #{displayEnabled},
    update_user_id = #{updateUserId}
WHERE monitor_task_id = #{monitorTaskId}
  AND deleted = 0

UPDATE campus_monitor_task
SET last_run_time = NOW(),
    last_run_log_id = #{lastRunLogId},
    update_user_id = #{updateUserId}
WHERE monitor_task_id = #{monitorTaskId}
  AND deleted = 0

UPDATE campus_monitor_task
SET next_run_time = #{nextRunTime},
    update_user_id = #{updateUserId}
WHERE monitor_task_id = #{monitorTaskId}
  AND deleted = 0
